-- Ledger service schema: double-entry journal, per-account balances and the event outbox.
-- Identifiers are UUIDv7 generated by the application. account_id is a plain value (the Account service owns the
-- account record); there are no foreign keys to other services' databases.
--
-- Sign convention: a CREDIT adds to and a DEBIT subtracts from an account's balance. A posted batch is balanced
-- (debits = credits per currency), so the sum of all balances in a currency is always zero.

-- A balanced, atomically posted set of entries. batch_ref is the caller's idempotency key; request_hash lets a replay
-- be told apart from a different request that reuses the same reference.
create table journal_batches
(
    id             uuid primary key,
    batch_ref      varchar(40) not null,
    source_service varchar(60) not null,
    source_event   varchar(120),
    request_hash   varchar(64) not null,
    status         varchar(20) not null default 'POSTED',
    correlation_id varchar(64),
    posted_by      uuid        not null,
    posted_at      timestamptz not null default now(),
    constraint journal_batches_batch_ref_key unique (batch_ref),
    constraint journal_batches_status_chk check (status in ('POSTED'))
);

-- Append-only ledger lines. Corrections are made with new, opposite entries, never by editing history.
create table ledger_entries
(
    id         uuid primary key,
    batch_id   uuid           not null references journal_batches (id),
    line_no    integer        not null,
    account_id uuid           not null,
    entry_type varchar(10)    not null,
    amount     numeric(19, 2) not null,
    currency   char(3)        not null,
    reference  varchar(140),
    posted_at  timestamptz    not null,
    constraint ledger_entries_batch_line_key unique (batch_id, line_no),
    constraint ledger_entries_line_chk check (line_no > 0),
    constraint ledger_entries_type_chk check (entry_type in ('DEBIT', 'CREDIT')),
    constraint ledger_entries_amount_chk check (amount > 0),
    constraint ledger_entries_currency_chk check (currency ~ '^[A-Z]{3}$')
);

-- Statements (newest first) and the reconciliation sum are served from this index alone: entry_type and amount are
-- included so neither query has to visit the table. (batch_id, line_no) above already serves "entries of a batch".
create index ledger_entries_account_posted_idx on ledger_entries (account_id, posted_at desc, id desc) include (entry_type, amount);

-- Current balance per account, changed only by postings (one atomic conditional UPDATE per account and posting).
-- balance_version is the monotonic sequence Account uses to ignore stale or duplicated snapshots.
-- fillfactor leaves room on each page so these frequent updates stay HOT (no index maintenance): the only index is
-- on the immutable account_id.
create table account_balances
(
    id                uuid primary key,
    account_id        uuid           not null,
    account_kind      varchar(10)    not null,
    currency          char(3)        not null,
    ledger_balance    numeric(19, 2) not null default 0,
    available_balance numeric(19, 2) not null default 0,
    balance_version   bigint         not null default 0,
    balance_as_of     timestamptz    not null default now(),
    created_at        timestamptz    not null default now(),
    updated_at        timestamptz    not null default now(),
    constraint account_balances_account_key unique (account_id),
    constraint account_balances_kind_chk check (account_kind in ('CUSTOMER', 'SYSTEM')),
    constraint account_balances_currency_chk check (currency ~ '^[A-Z]{3}$'),
    -- Last line of defence: customers can never be overdrawn, whatever the application does.
    constraint account_balances_customer_chk check (account_kind = 'SYSTEM' or (ledger_balance >= 0 and available_balance >= 0))
) with (fillfactor = 70);

-- Journal history is immutable at the database level too.
create function reject_ledger_history_change() returns trigger
    language plpgsql as
$$
begin
    raise exception '% is append-only (% rejected)', tg_table_name, tg_op;
end;
$$;

create trigger ledger_entries_append_only
    before update or delete on ledger_entries
    for each row execute function reject_ledger_history_change();
create trigger ledger_entries_no_truncate
    before truncate on ledger_entries
    for each statement execute function reject_ledger_history_change();
create trigger journal_batches_append_only
    before update or delete on journal_batches
    for each row execute function reject_ledger_history_change();

-- Transactional outbox (ADR-006): rows are written in the same transaction as the posting.
-- A publisher that relays them to the broker is a later step; published_at stays null until then.
create table outbox_events
(
    id             uuid primary key,
    aggregate_type varchar(50)  not null,
    aggregate_id   uuid         not null,
    event_type     varchar(100) not null,
    payload        jsonb        not null,
    correlation_id varchar(64),
    created_at     timestamptz  not null default now(),
    published_at   timestamptz
);

create index outbox_events_unpublished_idx on outbox_events (created_at) where published_at is null;
